{
  "story": "Diffusion models destroy images with noise step by step, then learn to reverse the process. Start from pure static, remove noise gradually, and reveal a clean photograph.",
  "aha": {
    "stateId": "step3",
    "observation": "At step three, recognizable shapes emerge from the chaotic static as the reverse process successfully predicts and subtracts the noise."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "metrics",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "bar",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Generation Step",
      "options": [
        "step0",
        "step1",
        "step2",
        "step3",
        "step4"
      ]
    },
    {
      "id": "resetState",
      "kind": "reset",
      "label": "Restart",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Standard Generation",
        "regions": [
          {
            "id": "canvas",
            "label": "Latent Space Canvas",
            "kind": "grid",
            "values": ["Static", "Noise", "Shapes", "Subject", "Clear"]
          }
        ],
        "states": [
          {
            "id": "step0",
            "label": "Pure Noise",
            "short": "Start",
            "sentence": "The model begins with completely random Gaussian noise.",
            "why": "Initial state has zero signal.",
            "active": ["canvas"],
            "calloutRegion": "canvas",
            "readouts": [
              {
                "id": "noiseLevel",
                "label": "Noise Level",
                "value": "100%"
              }
            ]
          },
          {
            "id": "step1",
            "label": "Early Denoising",
            "short": "Step 1",
            "sentence": "The neural network predicts and removes the first layer of noise.",
            "why": "Broad outlines start to cluster.",
            "active": ["canvas"],
            "calloutRegion": "canvas",
            "readouts": [
              {
                "id": "noiseLevel",
                "label": "Noise Level",
                "value": "75%"
              }
            ]
          },
          {
            "id": "step2",
            "label": "Mid Denoising",
            "short": "Step 2",
            "sentence": "Intermediate features and color blobs take form.",
            "why": "Structural composition locks in.",
            "active": ["canvas"],
            "calloutRegion": "canvas",
            "readouts": [
              {
                "id": "noiseLevel",
                "label": "Noise Level",
                "value": "50%"
              }
            ]
          },
          {
            "id": "step3",
            "label": "Late Denoising",
            "short": "Step 3",
            "sentence": "Fine details, textures, and edges sharpen rapidly.",
            "why": "High frequency details are restored.",
            "active": ["canvas"],
            "calloutRegion": "canvas",
            "readouts": [
              {
                "id": "noiseLevel",
                "label": "Noise Level",
                "value": "25%"
              }
            ]
          },
          {
            "id": "step4",
            "label": "Final Image",
            "short": "Done",
            "sentence": "The final clean image is fully realized.",
            "why": "Zero residual noise remains.",
            "active": ["canvas"],
            "calloutRegion": "canvas",
            "readouts": [
              {
                "id": "noiseLevel",
                "label": "Noise Level",
                "value": "0%"
              }
            ]
          }
        ]
      }
    ]
  }
}
